export default JSON.parse("{\"workId\":\"mo-zi\",\"chapter\":{\"id\":\"mo-zi_ch-67\",\"workId\":\"mo-zi\",\"order\":67,\"title\":\"雜守\",\"difficulty\":5,\"estimatedMinutes\":9,\"passageIds\":[\"mo-zi_ch-67_p-1\",\"mo-zi_ch-67_p-2\",\"mo-zi_ch-67_p-3\",\"mo-zi_ch-67_p-4\",\"mo-zi_ch-67_p-5\",\"mo-zi_ch-67_p-6\",\"mo-zi_ch-67_p-7\",\"mo-zi_ch-67_p-8\",\"mo-zi_ch-67_p-9\",\"mo-zi_ch-67_p-10\",\"mo-zi_ch-67_p-11\",\"mo-zi_ch-67_p-12\",\"mo-zi_ch-67_p-13\",\"mo-zi_ch-67_p-14\",\"mo-zi_ch-67_p-15\",\"mo-zi_ch-67_p-16\",\"mo-zi_ch-67_p-17\",\"mo-zi_ch-67_p-18\",\"mo-zi_ch-67_p-19\",\"mo-zi_ch-67_p-20\",\"mo-zi_ch-67_p-21\",\"mo-zi_ch-67_p-22\"],\"tags\":[\"墨家\",\"墨子\"]},\"passages\":[{\"id\":\"mo-zi_ch-67_p-1\",\"chapterId\":\"mo-zi_ch-67\",\"order\":1,\"canonicalText\":\"禽子問曰：「客眾而勇，輕意見威，以駭主人。薪土俱上，以為羊坽，積土為高，以臨吾民，蒙櫓俱前，遂屬之城，兵弩俱上，為之柰何？」\",\"sentenceIds\":[\"mo-zi_ch-67_p-1_s-1\",\"mo-zi_ch-67_p-1_s-2\",\"mo-zi_ch-67_p-1_s-3\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 1 節）中論述道：禽子問推理說理道：：客眾而且勇，輕意見威，以駭主人。薪土俱上，以為羊坽，積土為高，以臨吾民，蒙櫓俱前，遂屬的城，兵弩俱上，為的柰何？這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 1 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「禽子問曰：「客眾而勇，輕意見威，以駭主人」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「禽子問曰：「客眾而勇，輕意見威，以駭主人。薪土俱上，……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-2\",\"chapterId\":\"mo-zi_ch-67\",\"order\":2,\"canonicalText\":\"子墨子曰：「子問羊坽之守邪？羊坽者攻之拙者也，足以勞卒，不足以害城。羊坽之攻，遠攻則遠禦，近攻則近禦，害不至城。矢石無休，左右趣射，蘭為柱後，望已固。厲吾銳卒，慎無使顧，守者重下，攻者輕去。養勇高奮，民心百倍，多執數賞，卒乃不怠。\",\"sentenceIds\":[\"mo-zi_ch-67_p-2_s-1\",\"mo-zi_ch-67_p-2_s-2\",\"mo-zi_ch-67_p-2_s-3\",\"mo-zi_ch-67_p-2_s-4\",\"mo-zi_ch-67_p-2_s-5\",\"mo-zi_ch-67_p-2_s-6\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 2 節）中論述道：墨子先生親自教導推理說理道：：子問羊坽的守邪？羊坽的人或事物範疇攻的拙的人或事物範疇啊，足以勞卒，不足以害城。羊坽的攻，遠攻則遠禦，近攻則近禦，害不至城。矢石無休，左右趣射，蘭為柱後，望已固。厲吾銳卒，慎無使顧，守的人或事物範疇重下，攻的人或事物範疇輕去。養勇高奮，民心百倍，多執數賞，卒乃不怠。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 2 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「子墨子曰：「子問羊坽之守邪」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「子墨子曰：「子問羊坽之守邪？羊坽者攻之拙者也，足以勞……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-3\",\"chapterId\":\"mo-zi_ch-67\",\"order\":3,\"canonicalText\":\"作土不休，不能禁禦，遂屬之城，以禦雲梯之法應之。凡待堙、衝、雲梯、臨之法，必應城以禦之，石不足，則以木槨之。左百步，右百步，繁下矢、石、沙、灰以雨之，薪火、水湯以濟之。選厲銳卒，慎無使顧，審賞行罰，以靜為故，從之以急，無使生慮，養勇高憤，民心百倍，多執數賞，卒乃不怠。衝、臨、梯皆以衝衝之。\",\"sentenceIds\":[\"mo-zi_ch-67_p-3_s-1\",\"mo-zi_ch-67_p-3_s-2\",\"mo-zi_ch-67_p-3_s-3\",\"mo-zi_ch-67_p-3_s-4\",\"mo-zi_ch-67_p-3_s-5\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 3 節）中論述道：作土不休，不能禁禦，遂屬的城，以禦雲梯的法應的。凡待堙、衝、雲梯、臨的法，必應城以禦的，石不足，則以木槨的。左百步，右百步，繁下矢、石、沙、灰以雨的，薪火、水湯以濟的。選厲銳卒，慎無使顧，審賞行罰，以靜為所以，從的以急，無使生慮，養勇高憤，民心百倍，多執數賞，卒乃不怠。衝、臨、梯皆以衝衝的。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 3 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「作土不休，不能禁禦，遂屬之城，以禦雲梯之法應之」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「作土不休，不能禁禦，遂屬之城，以禦雲梯之法應之。凡待……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-4\",\"chapterId\":\"mo-zi_ch-67\",\"order\":4,\"canonicalText\":\"渠長丈五尺，其埋者三尺，夫長丈二尺。渠廣丈六尺，其梯丈二尺，荅之垂者四尺。樹渠無傅堞五寸，梯渠十丈一梯，渠荅大數，裏二百五十八，渠荅百二十九。\",\"sentenceIds\":[\"mo-zi_ch-67_p-4_s-1\",\"mo-zi_ch-67_p-4_s-2\",\"mo-zi_ch-67_p-4_s-3\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 4 節）中論述道：渠長丈五尺，他的埋的人或事物範疇三尺，夫長丈二尺。渠廣丈六尺，他的梯丈二尺，荅的垂的人或事物範疇四尺。樹渠無傅堞五寸，梯渠十丈一梯，渠荅大數，裏二百五十八，渠荅百二十九。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 4 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「渠長丈五尺，其埋者三尺，夫長丈二尺」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「渠長丈五尺，其埋者三尺，夫長丈二尺。渠廣丈六尺，其梯……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-5\",\"chapterId\":\"mo-zi_ch-67\",\"order\":5,\"canonicalText\":\"諸外道可要塞以難寇，其甚害者為築三亭，亭三隅，織女之，令能相救。諸鉅阜、山林、溝瀆、丘陵、阡陌、郭門、若閻術，可要塞及為微識，可以跡知往來者少多及所伏藏之處。\",\"sentenceIds\":[\"mo-zi_ch-67_p-5_s-1\",\"mo-zi_ch-67_p-5_s-2\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 5 節）中論述道：諸外道可要塞以難寇，他的甚害的人或事物範疇為築三亭，亭三隅，織女的，令能相救。諸鉅阜、山林、溝瀆、丘陵、阡陌、郭門、若閻術，可要塞及為微識，可以跡知往來的人或事物範疇少多及所伏藏的處。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 5 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「諸外道可要塞以難寇，其甚害者為築三亭，亭三隅，織女之，令能相救」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「諸外道可要塞以難寇，其甚害者為築三亭，亭三隅，織女之……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-6\",\"chapterId\":\"mo-zi_ch-67\",\"order\":6,\"canonicalText\":\"葆民，先舉城中官府、民宅、室署，大小調處，葆者或欲從兄弟、知識者許之。外宅粟米、畜產、財物諸可以佐城者，送入城中，事即急，則使積門內。民獻粟米布帛金錢牛馬畜產，皆為置平價，與主券書之。\",\"sentenceIds\":[\"mo-zi_ch-67_p-6_s-1\",\"mo-zi_ch-67_p-6_s-2\",\"mo-zi_ch-67_p-6_s-3\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 6 節）中論述道：葆民，先舉城中官府、民宅、室署，大小調處，葆的人或事物範疇或欲從兄弟、知識的人或事物範疇許的。外宅粟米、畜產、財物諸可以佐城的人或事物範疇，送入城中，事即急，則使積門內。民獻粟米布帛金錢牛馬畜產，皆為置平價，與主券書的。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 6 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「葆民，先舉城中官府、民宅、室署，大小調處，葆者或欲從兄弟、知識者許之」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「葆民，先舉城中官府、民宅、室署，大小調處，葆者或欲從……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-7\",\"chapterId\":\"mo-zi_ch-67\",\"order\":7,\"canonicalText\":\"使人各得其所長，天下事當，均其分職，天下事得，皆其所喜，天下事備，強弱有數，天下事具矣。\",\"sentenceIds\":[\"mo-zi_ch-67_p-7_s-1\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 7 節）中論述道：使人各得他的所長，天下事當，均他的分職，天下事得，皆他的所喜，天下事備，強弱有數，天下事具矣。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 7 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「使人各得其所長，天下事當，均其分職，天下事得，皆其所喜，天下事備，強弱有數，天下事具矣」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「使人各得其所長，天下事當，均其分職，天下事得，皆其所……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-8\",\"chapterId\":\"mo-zi_ch-67\",\"order\":8,\"canonicalText\":\"築郵亭者圜之，高三丈以上，令倚殺。為臂梯，梯兩臂長三丈，連版三尺，報以繩連之。塹再匝，為縣梁。壟竈，亭一鼓。寇烽、警烽、亂烽，傳火以次應之，至主國止，其事急者引而上下之。烽火已舉，輒五鼓傳，又以火屬之，言寇所從來者少多，毋弇建，去來屬次烽勿罷。望見寇，舉一烽；入境，舉二烽；射要，舉三烽三鼓；郭會，舉四烽四鼓；城會，舉五烽五鼓；夜以火，如此數。守烽者事急。\",\"sentenceIds\":[\"mo-zi_ch-67_p-8_s-1\",\"mo-zi_ch-67_p-8_s-2\",\"mo-zi_ch-67_p-8_s-3\",\"mo-zi_ch-67_p-8_s-4\",\"mo-zi_ch-67_p-8_s-5\",\"mo-zi_ch-67_p-8_s-6\",\"mo-zi_ch-67_p-8_s-7\",\"mo-zi_ch-67_p-8_s-8\",\"mo-zi_ch-67_p-8_s-9\",\"mo-zi_ch-67_p-8_s-10\",\"mo-zi_ch-67_p-8_s-11\",\"mo-zi_ch-67_p-8_s-12\",\"mo-zi_ch-67_p-8_s-13\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 8 節）中論述道：築郵亭的人或事物範疇圜的，高三丈以上，令倚殺。為臂梯，梯兩臂長三丈，連版三尺，報以繩連的。塹再匝，為縣梁。壟竈，亭一鼓。寇烽、警烽、亂烽，傳火以次應的，至主國止，他的事急的人或事物範疇引而且上下的。烽火已舉，輒五鼓傳，又以火屬的，言寇所從來的人或事物範疇少多，毋弇建，去來屬次烽勿罷。望見寇，舉一烽；入境，舉二烽；射要，舉三烽三鼓；郭會，舉四烽四鼓；城會，舉五烽五鼓；夜以火，如此數。守烽的人或事物範疇事急。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 8 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「築郵亭者圜之，高三丈以上，令倚殺」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「築郵亭者圜之，高三丈以上，令倚殺。為臂梯，梯兩臂長三……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-9\",\"chapterId\":\"mo-zi_ch-67\",\"order\":9,\"canonicalText\":\"候無過五十，寇至堞，隨去之，無弇逮。日暮出之，令皆為微識。距阜、山林，皆令可以跡，平明而跡，跡者無下里三人，各立其表，城上應之。候出置田表，斥坐郭內外立旗幟，卒半在內，令多少無可知。即有警，舉外表，見寇，舉次表。城上以麾指之，斥坐鼓整旗，以戰備從麾所指。田者男子以戰備從斥，女子亟走入。即見寇，鼓傳到城止。守表者三人，更立郵表而望，守數令騎若吏行旁視，有以知其所為。其曹一鼓。望見寇，鼓傳到城止。\",\"sentenceIds\":[\"mo-zi_ch-67_p-9_s-1\",\"mo-zi_ch-67_p-9_s-2\",\"mo-zi_ch-67_p-9_s-3\",\"mo-zi_ch-67_p-9_s-4\",\"mo-zi_ch-67_p-9_s-5\",\"mo-zi_ch-67_p-9_s-6\",\"mo-zi_ch-67_p-9_s-7\",\"mo-zi_ch-67_p-9_s-8\",\"mo-zi_ch-67_p-9_s-9\",\"mo-zi_ch-67_p-9_s-10\",\"mo-zi_ch-67_p-9_s-11\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 9 節）中論述道：候無過五十，寇至堞，隨去的，無弇逮。日暮出的，令皆為微識。距阜、山林，皆令可以跡，平明而且跡，跡的人或事物範疇無下里三人，各立他的表，城上應的。候出置田表，斥坐郭內外立旗幟，卒半在內，令多少無可知。即有警，舉外表，見寇，舉次表。城上以麾指的，斥坐鼓整旗，以戰備從麾所指。田的人或事物範疇男子以戰備從斥，女子亟走入。即見寇，鼓傳到城止。守表的人或事物範疇三人，更立郵表而且望，守數令騎若吏行旁視，有以知他的所為。他的曹一鼓。望見寇，鼓傳到城止。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 9 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「候無過五十，寇至堞，隨去之，無弇逮」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「候無過五十，寇至堞，隨去之，無弇逮。日暮出之，令皆為……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-10\",\"chapterId\":\"mo-zi_ch-67\",\"order\":10,\"canonicalText\":\"斗食，終歲三十六石；參食，終歲二十四石；四食，終歲十八石；五食，終歲十四石四鬥；六食，終歲十二石。斗食食五升，參食食參升小半，四食食二升半，五食食二升，六食食一升大半，日再食。救死之時，日二升者二十日，日三升者三十日，日四升者四十日，如是，而民免於九十日之約矣。\",\"sentenceIds\":[\"mo-zi_ch-67_p-10_s-1\",\"mo-zi_ch-67_p-10_s-2\",\"mo-zi_ch-67_p-10_s-3\",\"mo-zi_ch-67_p-10_s-4\",\"mo-zi_ch-67_p-10_s-5\",\"mo-zi_ch-67_p-10_s-6\",\"mo-zi_ch-67_p-10_s-7\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 10 節）中論述道：斗食，終歲三十六石；參食，終歲二十四石；四食，終歲十八石；五食，終歲十四石四鬥；六食，終歲十二石。斗食食五升，參食食參升小半，四食食二升半，五食食二升，六食食一升大半，日再食。救死的時，日二升的人或事物範疇二十日，日三升的人或事物範疇三十日，日四升的人或事物範疇四十日，如是，而且民免於九十日的約矣。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 10 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「斗食，終歲三十六石」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「斗食，終歲三十六石；參食，終歲二十四石；四食，終歲十……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-11\",\"chapterId\":\"mo-zi_ch-67\",\"order\":11,\"canonicalText\":\"寇近，亟收諸離鄉金器，若銅鐵及他可以佐守事者。先舉縣官室居、官府不急者，材之大小長短及凡數，即急先發。寇薄，發屋，伐木，雖有請謁，勿聽。入柴，勿積魚鱗簪，當遂，令易取也。材木不能盡入者，燔之，無令寇得用之。積木，各以長短大小惡美形相從，城四面外各積其內，諸木大者皆以為關鼻，乃積聚之。\",\"sentenceIds\":[\"mo-zi_ch-67_p-11_s-1\",\"mo-zi_ch-67_p-11_s-2\",\"mo-zi_ch-67_p-11_s-3\",\"mo-zi_ch-67_p-11_s-4\",\"mo-zi_ch-67_p-11_s-5\",\"mo-zi_ch-67_p-11_s-6\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 11 節）中論述道：寇近，亟收諸離鄉金器，若銅鐵及他可以佐守事的人或事物範疇。先舉縣官室居、官府不急的人或事物範疇，材的大小長短及凡數，即急先發。寇薄，發屋，伐木，雖有請謁，勿聽。入柴，勿積魚鱗簪，當遂，令易取啊。材木不能盡入的人或事物範疇，燔的，無令寇得用的。積木，各以長短大小惡美形相從，城四面外各積他的內，諸木大的人或事物範疇皆以為關鼻，乃積聚的。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 11 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「寇近，亟收諸離鄉金器，若銅鐵及他可以佐守事者」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「寇近，亟收諸離鄉金器，若銅鐵及他可以佐守事者。先舉縣……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-12\",\"chapterId\":\"mo-zi_ch-67\",\"order\":12,\"canonicalText\":\"城守司馬以上，父母、昆弟、妻子，有質在主所，乃可以堅守。署都司空，大城四人，候二人，縣候面一，亭尉、次司空、亭一人。吏侍守所者才足，廉信，父母昆弟妻子又在葆宮中者，乃得為侍吏。諸吏必有質，乃得任事。守大門者二人，夾門而立，令行者趣其外。各四戟，夾門立，而其人坐其下。吏日五閱之，上逋者名。\",\"sentenceIds\":[\"mo-zi_ch-67_p-12_s-1\",\"mo-zi_ch-67_p-12_s-2\",\"mo-zi_ch-67_p-12_s-3\",\"mo-zi_ch-67_p-12_s-4\",\"mo-zi_ch-67_p-12_s-5\",\"mo-zi_ch-67_p-12_s-6\",\"mo-zi_ch-67_p-12_s-7\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 12 節）中論述道：城守司馬以上，父母、昆弟、妻子，有質在主所，乃可以堅守。署都司空，大城四人，候二人，縣候面一，亭尉、次司空、亭一人。吏侍守所的人或事物範疇才足，廉信，父母昆弟妻子又在葆宮中的人或事物範疇，乃得為侍吏。諸吏必有質，乃得任事。守大門的人或事物範疇二人，夾門而且立，令行的人或事物範疇趣他的外。各四戟，夾門立，而且他的人坐他的下。吏日五閱的，上逋的人或事物範疇概念名詞。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 12 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「城守司馬以上，父母、昆弟、妻子，有質在主所，乃可以堅守」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「城守司馬以上，父母、昆弟、妻子，有質在主所，乃可以堅……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-13\",\"chapterId\":\"mo-zi_ch-67\",\"order\":13,\"canonicalText\":\"池外廉有要有害，必為疑人，令往來行夜者射之，誅其疏者。牆外水中，為竹箭，箭尺廣二步，箭下於水五寸，雜長短，前外廉三行，外外向，內亦內向。三十步一弩廬，廬廣十尺，長丈二尺。\",\"sentenceIds\":[\"mo-zi_ch-67_p-13_s-1\",\"mo-zi_ch-67_p-13_s-2\",\"mo-zi_ch-67_p-13_s-3\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 13 節）中論述道：池外廉有要有害，必為疑人，令往來行夜的人或事物範疇射的，誅他的疏的人或事物範疇。牆外水中，為竹箭，箭尺廣二步，箭下於水五寸，雜長短，前外廉三行，外外向，內亦內向。三十步一弩廬，廬廣十尺，長丈二尺。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 13 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「池外廉有要有害，必為疑人，令往來行夜者射之，誅其疏者」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「池外廉有要有害，必為疑人，令往來行夜者射之，誅其疏者……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-14\",\"chapterId\":\"mo-zi_ch-67\",\"order\":14,\"canonicalText\":\"隊有急，亟發其近者往佐，其次襲其處。\",\"sentenceIds\":[\"mo-zi_ch-67_p-14_s-1\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 14 節）中論述道：隊有急，亟發他的近的人或事物範疇往佐，他的次襲他的處。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 14 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「隊有急，亟發其近者往佐，其次襲其處」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「隊有急，亟發其近者往佐，其次襲其處。」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-15\",\"chapterId\":\"mo-zi_ch-67\",\"order\":15,\"canonicalText\":\"守節出入，使主節必疏書，署其情，令若其事，而須其還報以檢驗之。節出，使所出門者，輒言節出時操者名。\",\"sentenceIds\":[\"mo-zi_ch-67_p-15_s-1\",\"mo-zi_ch-67_p-15_s-2\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 15 節）中論述道：守節出入，使主節必疏書，署他的情，令若他的事，而且須他的還報以檢驗的。節出，使所出門的人或事物範疇，輒言節出時操的人或事物範疇概念名詞。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 15 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「守節出入，使主節必疏書，署其情，令若其事，而須其還報以檢驗之」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「守節出入，使主節必疏書，署其情，令若其事，而須其還報……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-16\",\"chapterId\":\"mo-zi_ch-67\",\"order\":16,\"canonicalText\":\"百步一隊。\",\"sentenceIds\":[\"mo-zi_ch-67_p-16_s-1\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 16 節）中論述道：百步一隊。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 16 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「百步一隊」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「百步一隊。」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-17\",\"chapterId\":\"mo-zi_ch-67\",\"order\":17,\"canonicalText\":\"閤通守舍，相錯穿室。治復道，為築墉，墉善其上。\",\"sentenceIds\":[\"mo-zi_ch-67_p-17_s-1\",\"mo-zi_ch-67_p-17_s-2\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 17 節）中論述道：閤通守舍，相錯穿室。治復道，為築墉，墉善他的上。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 17 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「閤通守舍，相錯穿室」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「閤通守舍，相錯穿室。治復道，為築墉，墉善其上。」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-18\",\"chapterId\":\"mo-zi_ch-67\",\"order\":18,\"canonicalText\":\"取蔬，令民家有三年蓄蔬食，以備湛旱、歲不為。常令邊縣豫種畜芫、芒、烏喙、椒葉，外宅溝井填可，塞不可，置此其中。安則示以危，危示以安。\",\"sentenceIds\":[\"mo-zi_ch-67_p-18_s-1\",\"mo-zi_ch-67_p-18_s-2\",\"mo-zi_ch-67_p-18_s-3\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 18 節）中論述道：取蔬，令民家有三年蓄蔬食，以備湛旱、歲不為。常令邊縣豫種畜芫、芒、烏喙、椒葉，外宅溝井填可，塞不可，置此他的中。安則示以危，危示以安。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 18 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「取蔬，令民家有三年蓄蔬食，以備湛旱、歲不為」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「取蔬，令民家有三年蓄蔬食，以備湛旱、歲不為。常令邊縣……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-19\",\"chapterId\":\"mo-zi_ch-67\",\"order\":19,\"canonicalText\":\"寇至，諸門戶令皆鑿而幎竅之，各為二類，一鑿而屬繩，繩長四尺，大如指。寇至，先殺牛、羊、彘、雞、狗、鳧、鴈，收其皮革、筋、角、脂、腦、羽皆剝之。使檟桐栗，為鐵錍，後蘭為衡柱。事急，卒不可遠，令掘外宅林。課多少，若治城上為擊，三隅之。重五斤以上諸林木，渥水中，無過一筏。塗茅屋若積薪者，厚五寸以上。吏各舉其部界中財物，可以佐守備者上。\",\"sentenceIds\":[\"mo-zi_ch-67_p-19_s-1\",\"mo-zi_ch-67_p-19_s-2\",\"mo-zi_ch-67_p-19_s-3\",\"mo-zi_ch-67_p-19_s-4\",\"mo-zi_ch-67_p-19_s-5\",\"mo-zi_ch-67_p-19_s-6\",\"mo-zi_ch-67_p-19_s-7\",\"mo-zi_ch-67_p-19_s-8\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 19 節）中論述道：寇至，諸門戶令皆鑿而且幎竅的，各為二類，一鑿而且屬繩，繩長四尺，大如指。寇至，先殺牛、羊、彘、雞、狗、鳧、鴈，收他的皮革、筋、角、脂、腦、羽皆剝的。使檟桐栗，為鐵錍，後蘭為衡柱。事急，卒不可遠，令掘外宅林。課多少，若治城上為擊，三隅的。重五斤以上諸林木，渥水中，無過一筏。塗茅屋若積薪的人或事物範疇，厚五寸以上。吏各舉他的部界中財物，可以佐守備的人或事物範疇上。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 19 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「寇至，諸門戶令皆鑿而幎竅之，各為二類，一鑿而屬繩，繩長四尺，大如指」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「寇至，諸門戶令皆鑿而幎竅之，各為二類，一鑿而屬繩，繩……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-20\",\"chapterId\":\"mo-zi_ch-67\",\"order\":20,\"canonicalText\":\"有讒人，有利人，有惡人，有善人，有長人，有謀士，有勇士，有巧士，有使士，有內人者，外人者，有善人者，有善鬥人者，守必察其所以然者，應名乃納之。民相惡，若議吏，吏所解，皆札書藏之，以須告者之至以參驗之。諸小睨五尺，不可卒者，為署吏，令給事官府若舍。\",\"sentenceIds\":[\"mo-zi_ch-67_p-20_s-1\",\"mo-zi_ch-67_p-20_s-2\",\"mo-zi_ch-67_p-20_s-3\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 20 節）中論述道：有讒人，有利人，有惡人，有善人，有長人，有謀士，有勇士，有巧士，有使士，有內人的人或事物範疇，外人的人或事物範疇，有善人的人或事物範疇，有善鬥人的人或事物範疇，守必察他的所以然的人或事物範疇，應概念名詞乃納的。民相惡，若議吏，吏所解，皆札書藏的，以須告的人或事物範疇的至以參驗的。諸小睨五尺，不可卒的人或事物範疇，為署吏，令給事官府若舍。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 20 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「有讒人，有利人，有惡人，有善人，有長人，有謀士，有勇士，有巧士，有使士，有內人者，外人者，有善人者，有善鬥人者，守必察其所以然者，應名乃納之」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「有讒人，有利人，有惡人，有善人，有長人，有謀士，有勇……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-21\",\"chapterId\":\"mo-zi_ch-67\",\"order\":21,\"canonicalText\":\"藺石、厲矢，諸材器用，皆謹部，各有積分數。為軺車以梓，載矢以軺車，輪轂，廣十尺，轅長丈，為四輪，廣六尺。為板箱，長與轅等，高四尺，善蓋上治中，令可載矢。」\",\"sentenceIds\":[\"mo-zi_ch-67_p-21_s-1\",\"mo-zi_ch-67_p-21_s-2\",\"mo-zi_ch-67_p-21_s-3\",\"mo-zi_ch-67_p-21_s-4\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 21 節）中論述道：藺石、厲矢，諸材器用，皆謹部，各有積分數。為軺車以梓，載矢以軺車，輪轂，廣十尺，轅長丈，為四輪，廣六尺。為板箱，長與轅等，高四尺，善蓋上治中，令可載矢。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 21 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「藺石、厲矢，諸材器用，皆謹部，各有積分數」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「藺石、厲矢，諸材器用，皆謹部，各有積分數。為軺車以梓……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"mo-zi_ch-67_p-22\",\"chapterId\":\"mo-zi_ch-67\",\"order\":22,\"canonicalText\":\"子墨子曰：「凡不守者有五：城大人少，一不守也；城小人眾，二不守也；人眾食寡，三不守也；市去城遠，四不守也；蓄積在外，富人在墟，五不守也。率萬家而城方三里。」\",\"sentenceIds\":[\"mo-zi_ch-67_p-22_s-1\",\"mo-zi_ch-67_p-22_s-2\",\"mo-zi_ch-67_p-22_s-3\",\"mo-zi_ch-67_p-22_s-4\",\"mo-zi_ch-67_p-22_s-5\",\"mo-zi_ch-67_p-22_s-6\",\"mo-zi_ch-67_p-22_s-7\"],\"sourceRefs\":[{\"label\":\"《墨子》—中國哲學書電子化計劃\",\"edition\":\"孫詒讓《墨子閒詁》本\",\"location\":\"https://ctext.org/mozi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《墨子》—維基文庫\",\"edition\":\"四部叢刊景明正統道藏本\",\"location\":\"https://zh.wikisource.org/zh-hant/墨子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【墨子白話通譯】在《墨子・雜守》（第 22 節）中論述道：墨子先生親自教導推理說理道：：凡不守的人或事物範疇有五：城大人少，一不守啊；城小人眾，二不守啊；人眾食寡，三不守啊；市去城遠，四不守啊；蓄積在外，富人在墟，五不守啊。率萬家而且城方三里。這段墨家典籍深刻闡發了兼愛非攻、尚賢節用、名辯邏輯與守城衛國之實踐真理。\",\"analysis\":\"【墨學篇旨與核心哲思】\\\\n本段選自先秦顯學鉅著《墨子》〈雜守〉（第 22 節）。文本依據清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》之權威體系，深刻闡發了墨家「兼相愛，交相利」、「尚賢尚同」、「非攻節用」與「天志明鬼」之核心綱領。開篇「子墨子曰：「凡不守者有五：城大人少，一不守也」奠定全篇之論述基石。\\\\n\\\\n【名辯邏輯與科技守城精義】\\\\n1. 墨辯邏輯與實踐哲學：全段聚焦「子墨子曰：「凡不守者有五：城大人少，一不守也；城小人……」，墨家首創古代名辯邏輯（名、辭、說、辯）與「三表法」（本、原、用），強調「言必有三表」，將認識論、名實論與社會功利實效緊密結合。\\\\n2. 科技實踐與城防守備：墨家學派精通古代幾何光學、力學工程與軍事守城體系，主張以嚴密之組織紀律與堅固城防捍衛弱小、制止兼併侵略。\\\\n\\\\n【兼愛天下與摩頂放踵精神】\\\\n墨子學派具有「摩頂放踵利天下為之」之偉大自我犧牲與人道主義精神，在戰國亂世之中為平民百姓之生存權利奔走呼號，代表了古代中國最具實踐力與平民情懷之崇高學派。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"mo-zi_ch-67_p-1_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-1\",\"order\":1,\"canonicalText\":\"禽子問曰：「客眾而勇，輕意見威，以駭主人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-1_s-2\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-1\",\"order\":2,\"canonicalText\":\"薪土俱上，以為羊坽，積土為高，以臨吾民，蒙櫓俱前，遂屬之城，兵弩俱上，為之柰何？\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-1_s-3\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-1\",\"order\":3,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-2_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-2\",\"order\":1,\"canonicalText\":\"子墨子曰：「子問羊坽之守邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-2_s-2\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-2\",\"order\":2,\"canonicalText\":\"羊坽者攻之拙者也，足以勞卒，不足以害城。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-2_s-3\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-2\",\"order\":3,\"canonicalText\":\"羊坽之攻，遠攻則遠禦，近攻則近禦，害不至城。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-2_s-4\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-2\",\"order\":4,\"canonicalText\":\"矢石無休，左右趣射，蘭為柱後，望已固。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-2_s-5\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-2\",\"order\":5,\"canonicalText\":\"厲吾銳卒，慎無使顧，守者重下，攻者輕去。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-2_s-6\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-2\",\"order\":6,\"canonicalText\":\"養勇高奮，民心百倍，多執數賞，卒乃不怠。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-3_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-3\",\"order\":1,\"canonicalText\":\"作土不休，不能禁禦，遂屬之城，以禦雲梯之法應之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-3_s-2\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-3\",\"order\":2,\"canonicalText\":\"凡待堙、衝、雲梯、臨之法，必應城以禦之，石不足，則以木槨之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-3_s-3\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-3\",\"order\":3,\"canonicalText\":\"左百步，右百步，繁下矢、石、沙、灰以雨之，薪火、水湯以濟之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-3_s-4\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-3\",\"order\":4,\"canonicalText\":\"選厲銳卒，慎無使顧，審賞行罰，以靜為故，從之以急，無使生慮，養勇高憤，民心百倍，多執數賞，卒乃不怠。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-3_s-5\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-3\",\"order\":5,\"canonicalText\":\"衝、臨、梯皆以衝衝之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-4_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-4\",\"order\":1,\"canonicalText\":\"渠長丈五尺，其埋者三尺，夫長丈二尺。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-4_s-2\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-4\",\"order\":2,\"canonicalText\":\"渠廣丈六尺，其梯丈二尺，荅之垂者四尺。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-4_s-3\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-4\",\"order\":3,\"canonicalText\":\"樹渠無傅堞五寸，梯渠十丈一梯，渠荅大數，裏二百五十八，渠荅百二十九。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-5_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-5\",\"order\":1,\"canonicalText\":\"諸外道可要塞以難寇，其甚害者為築三亭，亭三隅，織女之，令能相救。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-5_s-2\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-5\",\"order\":2,\"canonicalText\":\"諸鉅阜、山林、溝瀆、丘陵、阡陌、郭門、若閻術，可要塞及為微識，可以跡知往來者少多及所伏藏之處。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-6_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-6\",\"order\":1,\"canonicalText\":\"葆民，先舉城中官府、民宅、室署，大小調處，葆者或欲從兄弟、知識者許之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-6_s-2\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-6\",\"order\":2,\"canonicalText\":\"外宅粟米、畜產、財物諸可以佐城者，送入城中，事即急，則使積門內。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-6_s-3\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-6\",\"order\":3,\"canonicalText\":\"民獻粟米布帛金錢牛馬畜產，皆為置平價，與主券書之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-7_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-7\",\"order\":1,\"canonicalText\":\"使人各得其所長，天下事當，均其分職，天下事得，皆其所喜，天下事備，強弱有數，天下事具矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-8_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-8\",\"order\":1,\"canonicalText\":\"築郵亭者圜之，高三丈以上，令倚殺。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-8_s-2\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-8\",\"order\":2,\"canonicalText\":\"為臂梯，梯兩臂長三丈，連版三尺，報以繩連之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-8_s-3\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-8\",\"order\":3,\"canonicalText\":\"塹再匝，為縣梁。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-8_s-4\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-8\",\"order\":4,\"canonicalText\":\"壟竈，亭一鼓。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-8_s-5\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-8\",\"order\":5,\"canonicalText\":\"寇烽、警烽、亂烽，傳火以次應之，至主國止，其事急者引而上下之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-8_s-6\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-8\",\"order\":6,\"canonicalText\":\"烽火已舉，輒五鼓傳，又以火屬之，言寇所從來者少多，毋弇建，去來屬次烽勿罷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-8_s-7\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-8\",\"order\":7,\"canonicalText\":\"望見寇，舉一烽；\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-8_s-8\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-8\",\"order\":8,\"canonicalText\":\"入境，舉二烽；\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-8_s-9\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-8\",\"order\":9,\"canonicalText\":\"射要，舉三烽三鼓；\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-8_s-10\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-8\",\"order\":10,\"canonicalText\":\"郭會，舉四烽四鼓；\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-8_s-11\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-8\",\"order\":11,\"canonicalText\":\"城會，舉五烽五鼓；\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-8_s-12\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-8\",\"order\":12,\"canonicalText\":\"夜以火，如此數。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-8_s-13\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-8\",\"order\":13,\"canonicalText\":\"守烽者事急。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-9_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-9\",\"order\":1,\"canonicalText\":\"候無過五十，寇至堞，隨去之，無弇逮。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-9_s-2\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-9\",\"order\":2,\"canonicalText\":\"日暮出之，令皆為微識。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-9_s-3\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-9\",\"order\":3,\"canonicalText\":\"距阜、山林，皆令可以跡，平明而跡，跡者無下里三人，各立其表，城上應之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-9_s-4\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-9\",\"order\":4,\"canonicalText\":\"候出置田表，斥坐郭內外立旗幟，卒半在內，令多少無可知。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-9_s-5\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-9\",\"order\":5,\"canonicalText\":\"即有警，舉外表，見寇，舉次表。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-9_s-6\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-9\",\"order\":6,\"canonicalText\":\"城上以麾指之，斥坐鼓整旗，以戰備從麾所指。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-9_s-7\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-9\",\"order\":7,\"canonicalText\":\"田者男子以戰備從斥，女子亟走入。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-9_s-8\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-9\",\"order\":8,\"canonicalText\":\"即見寇，鼓傳到城止。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-9_s-9\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-9\",\"order\":9,\"canonicalText\":\"守表者三人，更立郵表而望，守數令騎若吏行旁視，有以知其所為。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-9_s-10\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-9\",\"order\":10,\"canonicalText\":\"其曹一鼓。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-9_s-11\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-9\",\"order\":11,\"canonicalText\":\"望見寇，鼓傳到城止。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-10_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-10\",\"order\":1,\"canonicalText\":\"斗食，終歲三十六石；\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-10_s-2\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-10\",\"order\":2,\"canonicalText\":\"參食，終歲二十四石；\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-10_s-3\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-10\",\"order\":3,\"canonicalText\":\"四食，終歲十八石；\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-10_s-4\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-10\",\"order\":4,\"canonicalText\":\"五食，終歲十四石四鬥；\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-10_s-5\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-10\",\"order\":5,\"canonicalText\":\"六食，終歲十二石。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-10_s-6\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-10\",\"order\":6,\"canonicalText\":\"斗食食五升，參食食參升小半，四食食二升半，五食食二升，六食食一升大半，日再食。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-10_s-7\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-10\",\"order\":7,\"canonicalText\":\"救死之時，日二升者二十日，日三升者三十日，日四升者四十日，如是，而民免於九十日之約矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-11_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-11\",\"order\":1,\"canonicalText\":\"寇近，亟收諸離鄉金器，若銅鐵及他可以佐守事者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-11_s-2\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-11\",\"order\":2,\"canonicalText\":\"先舉縣官室居、官府不急者，材之大小長短及凡數，即急先發。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-11_s-3\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-11\",\"order\":3,\"canonicalText\":\"寇薄，發屋，伐木，雖有請謁，勿聽。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-11_s-4\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-11\",\"order\":4,\"canonicalText\":\"入柴，勿積魚鱗簪，當遂，令易取也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-11_s-5\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-11\",\"order\":5,\"canonicalText\":\"材木不能盡入者，燔之，無令寇得用之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-11_s-6\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-11\",\"order\":6,\"canonicalText\":\"積木，各以長短大小惡美形相從，城四面外各積其內，諸木大者皆以為關鼻，乃積聚之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-12_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-12\",\"order\":1,\"canonicalText\":\"城守司馬以上，父母、昆弟、妻子，有質在主所，乃可以堅守。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-12_s-2\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-12\",\"order\":2,\"canonicalText\":\"署都司空，大城四人，候二人，縣候面一，亭尉、次司空、亭一人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-12_s-3\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-12\",\"order\":3,\"canonicalText\":\"吏侍守所者才足，廉信，父母昆弟妻子又在葆宮中者，乃得為侍吏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-12_s-4\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-12\",\"order\":4,\"canonicalText\":\"諸吏必有質，乃得任事。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-12_s-5\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-12\",\"order\":5,\"canonicalText\":\"守大門者二人，夾門而立，令行者趣其外。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-12_s-6\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-12\",\"order\":6,\"canonicalText\":\"各四戟，夾門立，而其人坐其下。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-12_s-7\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-12\",\"order\":7,\"canonicalText\":\"吏日五閱之，上逋者名。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-13_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-13\",\"order\":1,\"canonicalText\":\"池外廉有要有害，必為疑人，令往來行夜者射之，誅其疏者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-13_s-2\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-13\",\"order\":2,\"canonicalText\":\"牆外水中，為竹箭，箭尺廣二步，箭下於水五寸，雜長短，前外廉三行，外外向，內亦內向。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-13_s-3\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-13\",\"order\":3,\"canonicalText\":\"三十步一弩廬，廬廣十尺，長丈二尺。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-14_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-14\",\"order\":1,\"canonicalText\":\"隊有急，亟發其近者往佐，其次襲其處。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-15_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-15\",\"order\":1,\"canonicalText\":\"守節出入，使主節必疏書，署其情，令若其事，而須其還報以檢驗之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-15_s-2\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-15\",\"order\":2,\"canonicalText\":\"節出，使所出門者，輒言節出時操者名。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-16_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-16\",\"order\":1,\"canonicalText\":\"百步一隊。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-17_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-17\",\"order\":1,\"canonicalText\":\"閤通守舍，相錯穿室。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-17_s-2\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-17\",\"order\":2,\"canonicalText\":\"治復道，為築墉，墉善其上。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-18_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-18\",\"order\":1,\"canonicalText\":\"取蔬，令民家有三年蓄蔬食，以備湛旱、歲不為。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-18_s-2\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-18\",\"order\":2,\"canonicalText\":\"常令邊縣豫種畜芫、芒、烏喙、椒葉，外宅溝井填可，塞不可，置此其中。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-18_s-3\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-18\",\"order\":3,\"canonicalText\":\"安則示以危，危示以安。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-19_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-19\",\"order\":1,\"canonicalText\":\"寇至，諸門戶令皆鑿而幎竅之，各為二類，一鑿而屬繩，繩長四尺，大如指。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-19_s-2\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-19\",\"order\":2,\"canonicalText\":\"寇至，先殺牛、羊、彘、雞、狗、鳧、鴈，收其皮革、筋、角、脂、腦、羽皆剝之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-19_s-3\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-19\",\"order\":3,\"canonicalText\":\"使檟桐栗，為鐵錍，後蘭為衡柱。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-19_s-4\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-19\",\"order\":4,\"canonicalText\":\"事急，卒不可遠，令掘外宅林。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-19_s-5\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-19\",\"order\":5,\"canonicalText\":\"課多少，若治城上為擊，三隅之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-19_s-6\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-19\",\"order\":6,\"canonicalText\":\"重五斤以上諸林木，渥水中，無過一筏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-19_s-7\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-19\",\"order\":7,\"canonicalText\":\"塗茅屋若積薪者，厚五寸以上。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-19_s-8\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-19\",\"order\":8,\"canonicalText\":\"吏各舉其部界中財物，可以佐守備者上。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-20_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-20\",\"order\":1,\"canonicalText\":\"有讒人，有利人，有惡人，有善人，有長人，有謀士，有勇士，有巧士，有使士，有內人者，外人者，有善人者，有善鬥人者，守必察其所以然者，應名乃納之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-20_s-2\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-20\",\"order\":2,\"canonicalText\":\"民相惡，若議吏，吏所解，皆札書藏之，以須告者之至以參驗之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-20_s-3\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-20\",\"order\":3,\"canonicalText\":\"諸小睨五尺，不可卒者，為署吏，令給事官府若舍。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-21_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-21\",\"order\":1,\"canonicalText\":\"藺石、厲矢，諸材器用，皆謹部，各有積分數。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-21_s-2\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-21\",\"order\":2,\"canonicalText\":\"為軺車以梓，載矢以軺車，輪轂，廣十尺，轅長丈，為四輪，廣六尺。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-21_s-3\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-21\",\"order\":3,\"canonicalText\":\"為板箱，長與轅等，高四尺，善蓋上治中，令可載矢。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-21_s-4\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-21\",\"order\":4,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-22_s-1\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-22\",\"order\":1,\"canonicalText\":\"子墨子曰：「凡不守者有五：城大人少，一不守也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-22_s-2\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-22\",\"order\":2,\"canonicalText\":\"城小人眾，二不守也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-22_s-3\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-22\",\"order\":3,\"canonicalText\":\"人眾食寡，三不守也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-22_s-4\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-22\",\"order\":4,\"canonicalText\":\"市去城遠，四不守也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-22_s-5\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-22\",\"order\":5,\"canonicalText\":\"蓄積在外，富人在墟，五不守也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-22_s-6\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-22\",\"order\":6,\"canonicalText\":\"率萬家而城方三里。\",\"chunks\":[],\"tags\":[]},{\"id\":\"mo-zi_ch-67_p-22_s-7\",\"workId\":\"mo-zi\",\"chapterId\":\"mo-zi_ch-67\",\"passageId\":\"mo-zi_ch-67_p-22\",\"order\":7,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
